// Blinded AI judgment of stories generated by story-personalization-eval.mjs.
//
// Rates every generated text on language difficulty, formality, depth, breadth
// and topic focus without revealing the preferences it was generated with, then
// aggregates the ratings per varied factor into a self-contained HTML report.
// Run `node scripts/story-personalization-judge.mjs --help`.

import { existsSync, readFileSync, readdirSync, writeFileSync, appendFileSync } from 'node:fs';
import path from 'node:path';
import { createInterface } from 'node:readline/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';

const rootDir = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const { AI_EVAL_JUDGE_MODEL, AI_REASONING_EFFORT, LABELS } = await import(
	pathToFileURL(path.join(rootDir, 'src/constants/ui-config.js'))
);

const ALL_LABELS = LABELS.map((label) => label.value);
const SCALE_MIN = 1;
const SCALE_MAX = 5;
const DIMENSIONS = [
	{ key: 'difficulty', name: 'Language difficulty', low: 'simple', high: 'advanced' },
	{ key: 'formality', name: 'Language formality', low: 'casual', high: 'formal' },
	{ key: 'depth', name: 'Depth of information', low: 'superficial', high: 'in-depth' },
	{ key: 'breadth', name: 'Breadth of information', low: 'narrow', high: 'broad' }
];

const HELP = `
Usage: node scripts/story-personalization-judge.mjs [--run <dir>] [options]

Judges the stories of an evaluation run blind (the judge sees neither the
preferences nor the configuration) and writes an HTML report.

Input:
  --run <dir>           Run directory with results.jsonl (default: newest under
                        eval-results/stories)

Judgment:
  --unit segment|chain  Judge each generated segment on its own, or all segments of a
                        retry concatenated as one story (default segment)
  --repeats <n>         Independent judgments per unit, to measure judge consistency
                        (default 1)
  --with-context        Also show the judge the place context the story was generated
                        from (titles and descriptions; never the preferences)
  --model <id>          Judge model (default ${AI_EVAL_JUDGE_MODEL})
  --concurrency <n>     Parallel judge requests (default 4)

Control:
  --report-only         Skip judging and rebuild the report from judgments.jsonl
  --dry-run             Only print the cost estimate
  --yes                 Skip the confirmation prompt
  --help                Show this help

Output (in the run directory):
  judgments.jsonl       One line per judgment (unit, repeat, ratings, topics, usage)
  judgments-summary.json  Aggregated statistics per factor level and configuration
  report.html           Self-contained report with charts, tables and judged texts
`;

function parseArgs(argv) {
	const args = {
		run: null,
		unit: 'segment',
		repeats: 1,
		withContext: false,
		model: AI_EVAL_JUDGE_MODEL,
		concurrency: 4,
		reportOnly: false,
		dryRun: false,
		yes: false
	};
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		const next = () => {
			const value = argv[++i];
			if (value === undefined) {
				throw new Error(`Missing value for ${arg}`);
			}
			return value;
		};
		switch (arg) {
			case '--help':
			case '-h':
				console.log(HELP);
				process.exit(0);
				break;
			case '--run':
				args.run = path.resolve(next());
				break;
			case '--unit':
				args.unit = next();
				if (!['segment', 'chain'].includes(args.unit)) {
					throw new Error('--unit expects "segment" or "chain"');
				}
				break;
			case '--repeats':
				args.repeats = parsePositiveInt(next(), arg);
				break;
			case '--with-context':
				args.withContext = true;
				break;
			case '--model':
				args.model = next();
				break;
			case '--concurrency':
				args.concurrency = parsePositiveInt(next(), arg);
				break;
			case '--report-only':
				args.reportOnly = true;
				break;
			case '--dry-run':
				args.dryRun = true;
				break;
			case '--yes':
			case '-y':
				args.yes = true;
				break;
			default:
				throw new Error(`Unknown argument: ${arg}`);
		}
	}
	if (!args.run) {
		args.run = findNewestRun();
	}
	if (!existsSync(path.join(args.run, 'results.jsonl'))) {
		throw new Error(`No results.jsonl in ${args.run}`);
	}
	return args;
}

function parsePositiveInt(value, flag) {
	const number = Number(value);
	if (!Number.isInteger(number) || number < 1) {
		throw new Error(`${flag} expects a positive integer, got "${value}"`);
	}
	return number;
}

function findNewestRun() {
	const runsDir = path.join(rootDir, 'eval-results', 'stories');
	if (!existsSync(runsDir)) {
		throw new Error('No evaluation runs found; pass --run <dir>');
	}
	const runs = readdirSync(runsDir)
		.filter((name) => existsSync(path.join(runsDir, name, 'results.jsonl')))
		.sort();
	if (!runs.length) {
		throw new Error('No evaluation runs with results.jsonl found; pass --run <dir>');
	}
	return path.join(runsDir, runs[runs.length - 1]);
}

function readJsonl(file) {
	if (!existsSync(file)) return [];
	return readFileSync(file, 'utf8')
		.split('\n')
		.filter((line) => line.trim())
		.map((line) => JSON.parse(line));
}

const out = (text = '') => process.stdout.write(`${text}\n`);

function displayPath(target) {
	const relative = path.relative(rootDir, target);
	return relative && !relative.startsWith('..') ? relative : target;
}

// Builds the judged units from the generation records: one per segment, or one
// per retry with all segments concatenated.
function buildUnits(records, unit) {
	const successful = records.filter((record) => record.text);
	if (unit === 'segment') {
		return successful.map((record) => ({
			id: `c${record.configId}-r${record.retry}-s${record.segment}`,
			configId: record.configId,
			configLabel: record.configLabel,
			contextId: record.contextId,
			retry: record.retry,
			segment: record.segment,
			varied: record.varied,
			preferences: record.preferences,
			text: record.text
		}));
	}
	const chains = new Map();
	for (const record of successful.sort((a, b) => a.segment - b.segment)) {
		const key = `c${record.configId}-r${record.retry}`;
		if (!chains.has(key)) {
			chains.set(key, {
				id: key,
				configId: record.configId,
				configLabel: record.configLabel,
				contextId: record.contextId,
				retry: record.retry,
				segment: null,
				varied: record.varied,
				preferences: record.preferences,
				texts: []
			});
		}
		chains.get(key).texts.push(record.text);
	}
	return [...chains.values()].map(({ texts, ...chain }) => ({
		...chain,
		text: texts.join('\n\n')
	}));
}

function loadContexts(runDir) {
	const contexts = new Map();
	const contextsDir = path.join(runDir, 'contexts');
	if (!existsSync(contextsDir)) return contexts;
	for (const name of readdirSync(contextsDir)) {
		if (!name.endsWith('.json')) continue;
		const context = JSON.parse(readFileSync(path.join(contextsDir, name), 'utf8'));
		contexts.set(context.id, context);
	}
	return contexts;
}

function describeContext(context) {
	if (!context) return '';
	const describe = (place) =>
		`- ${place.title}: ${place.description || place.snippet || place.type || ''}`.trim();
	return `
The text was generated from the following place information (this is the material available to the author, not a rating criterion):

Places at the position:
${context.placesHere.map(describe).join('\n') || '- none'}

Nearby places:
${context.placesNearby.slice(0, 5).map(describe).join('\n') || '- none'}

Surrounding area:
${context.placesSurrounding.map(describe).join('\n') || '- none'}
`;
}

function getJudgeInstructions() {
	return `You are an expert analyst of texts for language and content. You rate short texts that a location guide app produced about a place.

Rate the text on the following dimensions, each as an integer from ${SCALE_MIN} to ${SCALE_MAX}:

- difficulty: language difficulty level. ${SCALE_MIN} = very simple (short sentences, everyday words, understandable for a child), ${SCALE_MAX} = very advanced (complex syntax, specialist vocabulary, dense argumentation).
- formality: language formality level. ${SCALE_MIN} = very casual (colloquial, playful, addresses the reader informally), ${SCALE_MAX} = very formal (neutral, distant, written standard).
- depth: depth of information. ${SCALE_MIN} = superficial (only generic statements), ${SCALE_MAX} = in-depth (specific facts, dates, names, explanations of causes and background).
- breadth: breadth of information. ${SCALE_MIN} = narrow (a single aspect of a single place), ${SCALE_MAX} = broad (many different places or aspects covered).

Then determine the topic focus: select every topic from the list below that the text substantially focuses on. A topic counts only if a noticeable part of the text is about it, not if it is mentioned in passing. Select none if no topic applies.

Available topics:
${LABELS.map((label) => `- ${label.value}: ${label.description}`).join('\n')}

Judge only the text itself. Do not guess or reward any intent behind it. Rate the language dimensions independently of the content dimensions, and be consistent: the same kind of text must always receive the same rating.

Give a one-sentence rationale that names the concrete features of the text that determined the ratings.`;
}

const JUDGMENT_SCHEMA = {
	type: 'object',
	additionalProperties: false,
	properties: {
		difficulty: { type: 'integer' },
		formality: { type: 'integer' },
		depth: { type: 'integer' },
		breadth: { type: 'integer' },
		topics: { type: 'array', items: { type: 'string', enum: ALL_LABELS } },
		rationale: { type: 'string' }
	},
	required: ['difficulty', 'formality', 'depth', 'breadth', 'topics', 'rationale']
};

async function judgeText(openai, model, text, contextDescription) {
	const response = await openai.responses.create({
		model,
		reasoning: { effort: AI_REASONING_EFFORT.JUDGE },
		input: [
			{ role: 'system', content: getJudgeInstructions() },
			{
				role: 'user',
				content: `${contextDescription}
Text to rate:

"""
${text}
"""`
			}
		],
		text: {
			format: {
				type: 'json_schema',
				name: 'story_judgment',
				strict: true,
				schema: JUDGMENT_SCHEMA
			}
		}
	});
	const judgment = JSON.parse(response.output_text);
	for (const dimension of DIMENSIONS) {
		const value = judgment[dimension.key];
		if (!Number.isInteger(value) || value < SCALE_MIN || value > SCALE_MAX) {
			throw new Error(
				`Judge returned ${dimension.key}=${value}, expected ${SCALE_MIN}-${SCALE_MAX}`
			);
		}
	}
	judgment.topics = [...new Set(judgment.topics.filter((topic) => ALL_LABELS.includes(topic)))];
	return { judgment, responseId: response.id, usage: response.usage || null };
}

async function confirm(question) {
	const rl = createInterface({ input: process.stdin, output: process.stdout });
	try {
		const answer = await rl.question(question);
		return /^y(es)?$/i.test(answer.trim());
	} finally {
		rl.close();
	}
}

async function runPool(tasks, concurrency) {
	let nextIndex = 0;
	const workers = Array.from({ length: Math.min(concurrency, tasks.length) }, async () => {
		while (nextIndex < tasks.length) {
			await tasks[nextIndex++]();
		}
	});
	await Promise.all(workers);
}

// ---------------------------------------------------------------------------
// Aggregation

function formatValue(key, value) {
	if (key === 'labels') {
		if (value.length === ALL_LABELS.length) return 'ALL';
		if (value.length === 0) return 'NONE';
		return value.join('+');
	}
	if (Array.isArray(value)) return value.join('+');
	return String(value);
}

function mean(values) {
	return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
}

function standardDeviation(values) {
	if (values.length < 2) return 0;
	const average = mean(values);
	return Math.sqrt(
		values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1)
	);
}

function round(value, digits = 2) {
	return value === null || value === undefined ? null : Number(value.toFixed(digits));
}

// Share of judged topics that lie within the preferred labels, and share of
// preferred labels the text focuses on. Only informative when not all labels
// are preferred.
function topicMatch(judgment, preferences) {
	const preferred = new Set(preferences?.labels || []);
	const judged = judgment.topics;
	const hits = judged.filter((topic) => preferred.has(topic)).length;
	return {
		precision: judged.length ? hits / judged.length : null,
		recall: preferred.size ? hits / preferred.size : null
	};
}

function summarizeGroup(rows) {
	const summary = {
		n: rows.length,
		dimensions: {},
		topics: {},
		topicPrecision: null,
		topicRecall: null
	};
	for (const dimension of DIMENSIONS) {
		const values = rows.map((row) => row.judgment[dimension.key]);
		summary.dimensions[dimension.key] = {
			mean: round(mean(values)),
			sd: round(standardDeviation(values)),
			histogram: Array.from(
				{ length: SCALE_MAX - SCALE_MIN + 1 },
				(_, index) => values.filter((value) => value === index + SCALE_MIN).length
			)
		};
	}
	for (const label of ALL_LABELS) {
		summary.topics[label] = round(
			rows.length
				? rows.filter((row) => row.judgment.topics.includes(label)).length / rows.length
				: null
		);
	}
	summary.topicsPerText = round(mean(rows.map((row) => row.judgment.topics.length)));
	const precisions = rows.map((row) => row.match.precision).filter((value) => value !== null);
	const recalls = rows.map((row) => row.match.recall).filter((value) => value !== null);
	summary.topicPrecision = round(mean(precisions));
	summary.topicRecall = round(mean(recalls));
	return summary;
}

function summarizeConsistency(rows) {
	const byUnit = new Map();
	for (const row of rows) {
		if (!byUnit.has(row.unitId)) byUnit.set(row.unitId, []);
		byUnit.get(row.unitId).push(row);
	}
	const multi = [...byUnit.values()].filter((group) => group.length > 1);
	if (!multi.length) return null;
	const consistency = { units: multi.length, dimensions: {}, topicJaccard: null };
	for (const dimension of DIMENSIONS) {
		consistency.dimensions[dimension.key] = round(
			mean(multi.map((group) => standardDeviation(group.map((row) => row.judgment[dimension.key]))))
		);
	}
	consistency.topicJaccard = round(
		mean(
			multi.map((group) => {
				const pairs = [];
				for (let a = 0; a < group.length; a++) {
					for (let b = a + 1; b < group.length; b++) {
						const setA = new Set(group[a].judgment.topics);
						const setB = new Set(group[b].judgment.topics);
						const union = new Set([...setA, ...setB]);
						const intersection = [...setA].filter((topic) => setB.has(topic)).length;
						pairs.push(union.size ? intersection / union.size : 1);
					}
				}
				return mean(pairs);
			})
		)
	);
	return consistency;
}

function aggregate(runMeta, rows) {
	const factors = runMeta.args?.vary || [];
	const summary = {
		overall: summarizeGroup(rows),
		factors: {},
		configs: [],
		consistency: summarizeConsistency(rows)
	};
	for (const factor of factors) {
		const levels = [];
		for (const config of runMeta.configs) {
			const level = formatValue(factor, config.overrides[factor]);
			if (!levels.includes(level)) levels.push(level);
		}
		summary.factors[factor] = levels.map((level) => ({
			level,
			...summarizeGroup(rows.filter((row) => formatValue(factor, row.varied[factor]) === level))
		}));
	}
	for (const config of runMeta.configs) {
		summary.configs.push({
			id: config.id,
			label: config.label,
			overrides: config.overrides,
			...summarizeGroup(rows.filter((row) => row.configId === config.id))
		});
	}
	return summary;
}

// ---------------------------------------------------------------------------
// Report

function escapeHtml(text) {
	return String(text ?? '')
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;');
}

function renderStoryText(text) {
	return text
		.split(/\n\s*\n/)
		.map((paragraph) => escapeHtml(paragraph.trim()))
		.filter(Boolean)
		.map((paragraph) => `<p>${paragraph.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')}</p>`)
		.join('');
}

const SEQUENTIAL_RAMP = [
	'#cde2fb',
	'#9ec5f4',
	'#6da7ec',
	'#3987e5',
	'#256abf',
	'#184f95',
	'#0d366b'
];

function rampColor(fraction) {
	if (!fraction) return 'var(--surface-2)';
	const index = Math.min(
		SEQUENTIAL_RAMP.length - 1,
		Math.max(0, Math.round(fraction * (SEQUENTIAL_RAMP.length - 1)))
	);
	return SEQUENTIAL_RAMP[index];
}

// Dot-and-whisker chart of one dimension: mean per level with ±1 SD.
function renderDimensionChart(dimension, groups, labelWidth = 170) {
	const rowHeight = 26;
	const plotWidth = 240;
	const width = labelWidth + plotWidth + 60;
	const height = groups.length * rowHeight + 34;
	const x = (value) => labelWidth + ((value - SCALE_MIN) / (SCALE_MAX - SCALE_MIN)) * plotWidth;
	const ticks = Array.from({ length: SCALE_MAX - SCALE_MIN + 1 }, (_, index) => index + SCALE_MIN);
	const parts = [];
	parts.push(
		`<svg class="chart" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${escapeHtml(dimension.name)} per level">`
	);
	for (const tick of ticks) {
		parts.push(
			`<line class="grid" x1="${x(tick)}" y1="6" x2="${x(tick)}" y2="${height - 28}"/>` +
				`<text class="tick" x="${x(tick)}" y="${height - 14}" text-anchor="middle">${tick}</text>`
		);
	}
	parts.push(
		`<text class="axis-label" x="${x(SCALE_MIN)}" y="${height - 2}" text-anchor="start">${escapeHtml(dimension.low)}</text>` +
			`<text class="axis-label" x="${x(SCALE_MAX)}" y="${height - 2}" text-anchor="end">${escapeHtml(dimension.high)}</text>`
	);
	groups.forEach((group, index) => {
		const cy = 6 + index * rowHeight + rowHeight / 2;
		const stats = group.dimensions[dimension.key];
		parts.push(
			`<text class="row-label" x="${labelWidth - 10}" y="${cy + 4}" text-anchor="end">${escapeHtml(truncate(group.level, 26))}</text>`
		);
		if (stats.mean === null) return;
		const low = Math.max(SCALE_MIN, stats.mean - stats.sd);
		const high = Math.min(SCALE_MAX, stats.mean + stats.sd);
		const tooltip = `${group.level}: mean ${stats.mean}, SD ${stats.sd}, n=${group.n}`;
		parts.push(
			`<g class="mark"><title>${escapeHtml(tooltip)}</title>` +
				`<line class="whisker" x1="${x(low)}" y1="${cy}" x2="${x(high)}" y2="${cy}"/>` +
				`<circle class="dot" cx="${x(stats.mean)}" cy="${cy}" r="5"/>` +
				`<text class="value" x="${labelWidth + plotWidth + 12}" y="${cy + 4}">${stats.mean.toFixed(2)}</text></g>`
		);
	});
	parts.push('</svg>');
	return parts.join('');
}

function truncate(text, length) {
	return text.length > length ? `${text.slice(0, length - 1)}…` : text;
}

// Heatmap of topic selection rates: levels × topics.
function renderTopicHeatmap(groups, labelWidth = 170) {
	const cell = 34;
	const width = labelWidth + ALL_LABELS.length * cell + 70;
	const headerHeight = 110;
	const height = headerHeight + groups.length * cell + 10;
	const parts = [
		`<svg class="chart heatmap" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="Topic focus per level">`
	];
	ALL_LABELS.forEach((label, column) => {
		const cx = labelWidth + column * cell + cell / 2;
		parts.push(
			`<text class="tick" transform="translate(${cx + 4} ${headerHeight - 6}) rotate(-60)" text-anchor="start">${escapeHtml(label)}</text>`
		);
	});
	groups.forEach((group, row) => {
		const y = headerHeight + row * cell;
		parts.push(
			`<text class="row-label" x="${labelWidth - 10}" y="${y + cell / 2 + 4}" text-anchor="end">${escapeHtml(truncate(group.level, 26))}</text>`
		);
		ALL_LABELS.forEach((label, column) => {
			const rate = group.topics[label];
			const xPos = labelWidth + column * cell;
			const textClass = rate === null || rate === 0 ? 'zero' : rate >= 0.5 ? 'on-dark' : 'on-light';
			const tooltip = `${group.level} × ${label}: ${rate === null ? 'n/a' : `${Math.round(rate * 100)}% of ${group.n} texts`}`;
			parts.push(
				`<g class="mark"><title>${escapeHtml(tooltip)}</title>` +
					`<rect x="${xPos + 1}" y="${y + 1}" width="${cell - 2}" height="${cell - 2}" rx="3" fill="${rampColor(rate)}"/>` +
					`<text class="cell-value ${textClass}" x="${xPos + cell / 2}" y="${y + cell / 2 + 4}" text-anchor="middle">${rate === null ? '' : Math.round(rate * 100)}</text></g>`
			);
		});
	});
	parts.push('</svg>');
	return parts.join('');
}

function renderGroupTable(groups, firstColumn) {
	const header = [
		firstColumn,
		'n',
		...DIMENSIONS.map((dimension) => `${dimension.name} (mean ± SD)`),
		'Topics per text',
		'Topic precision',
		'Topic recall',
		'Topics ≥ 50%'
	];
	const rows = groups.map((group) => {
		const cells = [
			escapeHtml(group.level ?? group.label),
			group.n,
			...DIMENSIONS.map((dimension) => {
				const stats = group.dimensions[dimension.key];
				return stats.mean === null ? '–' : `${stats.mean.toFixed(2)} ± ${stats.sd.toFixed(2)}`;
			}),
			group.topicsPerText ?? '–',
			formatRate(group.topicPrecision),
			formatRate(group.topicRecall),
			escapeHtml(
				ALL_LABELS.filter(
					(label) => group.topics[label] !== null && group.topics[label] >= 0.5
				).join(', ') || '–'
			)
		];
		return `<tr>${cells.map((cellValue) => `<td>${cellValue}</td>`).join('')}</tr>`;
	});
	return `<table><thead><tr>${header.map((cellValue) => `<th>${escapeHtml(cellValue)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;
}

function formatRate(value) {
	return value === null || value === undefined ? '–' : `${Math.round(value * 100)}%`;
}

function renderFactorSection(factor, groups) {
	const charts = DIMENSIONS.map(
		(dimension) =>
			`<figure><figcaption>${escapeHtml(dimension.name)}</figcaption>${renderDimensionChart(dimension, groups)}</figure>`
	).join('');
	return `<section>
<h2>Factor: ${escapeHtml(factor)}</h2>
<p class="muted">Mean rating per level with ±1 SD whiskers on the ${SCALE_MIN}–${SCALE_MAX} scale; the heatmap shows the share of texts the judge saw focusing on each topic.</p>
<div class="chart-grid">${charts}</div>
<figure><figcaption>Topic focus (% of texts)</figcaption>${renderTopicHeatmap(groups)}</figure>
<details><summary>Table view</summary>${renderGroupTable(groups, 'Level')}</details>
</section>`;
}

function renderJudgedTexts(runMeta, rows, units) {
	const rowsByUnit = new Map();
	for (const row of rows) {
		if (!rowsByUnit.has(row.unitId)) rowsByUnit.set(row.unitId, []);
		rowsByUnit.get(row.unitId).push(row);
	}
	const sections = runMeta.configs.map((config) => {
		const configUnits = units
			.filter((unit) => unit.configId === config.id)
			.sort((a, b) => a.retry - b.retry || (a.segment ?? 0) - (b.segment ?? 0));
		const items = configUnits.map((unit) => {
			const unitRows = (rowsByUnit.get(unit.id) || []).sort((a, b) => a.repeat - b.repeat);
			const judgments = unitRows.map((row) => {
				const ratings = DIMENSIONS.map(
					(dimension) =>
						`<span class="pill">${escapeHtml(dimension.name)}: ${row.judgment[dimension.key]}</span>`
				).join('');
				const topics = row.judgment.topics.length
					? row.judgment.topics
							.map((topic) => `<span class="pill topic">${escapeHtml(topic)}</span>`)
							.join('')
					: '<span class="pill topic">no topic</span>';
				return `<div class="judgment">${unitRows.length > 1 ? `<span class="muted">Judgment ${row.repeat}:</span> ` : ''}${ratings}${topics}<p class="rationale">${escapeHtml(row.judgment.rationale)}</p></div>`;
			});
			return `<article class="judged">
<header>Retry ${unit.retry}${unit.segment ? `, segment ${unit.segment}` : ''}</header>
<div class="story">${renderStoryText(unit.text)}</div>
${judgments.join('') || '<p class="muted">No successful judgment.</p>'}
</article>`;
		});
		const judgmentCount = configUnits.reduce(
			(sum, unit) => sum + (rowsByUnit.get(unit.id)?.length || 0),
			0
		);
		return `<details class="config"><summary>Configuration ${config.id}: ${escapeHtml(config.label || 'defaults')} <span class="muted">(${configUnits.length} texts, ${judgmentCount} judgments)</span></summary>${items.join('')}</details>`;
	});
	return sections.join('');
}

function renderReport(runMeta, judgeMeta, summary, rows, units) {
	const factors = Object.keys(summary.factors);
	const factorSections = factors
		.map((factor) => renderFactorSection(factor, summary.factors[factor]))
		.join('');
	const consistency = summary.consistency
		? `<section><h2>Judge consistency</h2><p>Across ${summary.consistency.units} units judged ${judgeMeta.repeats} times each: mean within-unit SD ${DIMENSIONS.map(
				(dimension) =>
					`${dimension.name.toLowerCase()} ${summary.consistency.dimensions[dimension.key]}`
			).join(
				', '
			)}; mean topic-set Jaccard similarity ${summary.consistency.topicJaccard}.</p></section>`
		: '';
	const location = runMeta.args ? `${runMeta.args.lat}, ${runMeta.args.lon}` : 'unknown';
	const contexts = (runMeta.contexts || [])
		.map(
			(context) =>
				`<li><strong>Context ${context.id}</strong> (${escapeHtml(context.address || '')}): here ${escapeHtml(context.here?.join('; ') || '–')}; surrounding ${escapeHtml(context.surrounding?.join('; ') || '–')}</li>`
		)
		.join('');
	return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Story Personalization Report</title>
<style>
:root {
	color-scheme: light;
	--surface-1: #fcfcfb;
	--surface-2: #f0efec;
	--border: #dcdad5;
	--text-primary: #0b0b0b;
	--text-secondary: #52514e;
	--text-muted: #7a7873;
	--series-1: #2a78d6;
	--grid: #e6e4df;
}
@media (prefers-color-scheme: dark) {
	:root:not([data-theme="light"]) {
		color-scheme: dark;
		--surface-1: #1a1a19;
		--surface-2: #262624;
		--border: #3a3a37;
		--text-primary: #ffffff;
		--text-secondary: #c3c2b7;
		--text-muted: #8f8e86;
		--series-1: #3987e5;
		--grid: #323230;
	}
}
:root[data-theme="dark"] {
	color-scheme: dark;
	--surface-1: #1a1a19;
	--surface-2: #262624;
	--border: #3a3a37;
	--text-primary: #ffffff;
	--text-secondary: #c3c2b7;
	--text-muted: #8f8e86;
	--series-1: #3987e5;
	--grid: #323230;
}
* { box-sizing: border-box; }
body { margin: 0; padding: 24px 16px 48px; background: var(--surface-1); color: var(--text-primary); font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
main { max-width: 1100px; margin: 0 auto; }
h1 { font-size: 26px; margin: 0 0 4px; }
h2 { font-size: 20px; margin: 40px 0 6px; }
.muted { color: var(--text-secondary); }
dl.meta { display: grid; grid-template-columns: max-content 1fr; gap: 2px 16px; margin: 12px 0; }
dl.meta dt { color: var(--text-secondary); }
dl.meta dd { margin: 0; }
.tiles { display: flex; flex-wrap: wrap; gap: 12px; margin: 16px 0; }
.tile { background: var(--surface-2); border-radius: 8px; padding: 10px 16px; min-width: 130px; }
.tile .num { font-size: 22px; font-weight: 600; }
.tile .lbl { color: var(--text-secondary); font-size: 13px; }
.chart-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(440px, 1fr)); gap: 12px 24px; }
figure { margin: 8px 0; overflow-x: auto; }
figcaption { font-weight: 600; margin-bottom: 4px; }
svg.chart { display: block; max-width: 100%; height: auto; font-family: inherit; }
svg .grid { stroke: var(--grid); stroke-width: 1; }
svg .tick, svg .axis-label { fill: var(--text-muted); font-size: 11px; }
svg .row-label { fill: var(--text-primary); font-size: 12px; }
svg .value { fill: var(--text-secondary); font-size: 12px; }
svg .whisker { stroke: var(--series-1); stroke-width: 2; stroke-linecap: round; opacity: 0.6; }
svg .dot { fill: var(--series-1); stroke: var(--surface-1); stroke-width: 2; }
svg .cell-value { font-size: 11px; }
svg .cell-value.zero { fill: var(--text-muted); }
svg .cell-value.on-light { fill: #0b0b0b; }
svg .cell-value.on-dark { fill: #ffffff; }
svg .mark:hover .dot { r: 7; }
table { border-collapse: collapse; width: 100%; font-size: 13px; margin: 8px 0; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border); vertical-align: top; }
th { color: var(--text-secondary); font-weight: 600; }
details { margin: 8px 0; }
summary { cursor: pointer; font-weight: 600; }
details.config { border: 1px solid var(--border); border-radius: 8px; padding: 8px 12px; }
article.judged { border-top: 1px solid var(--border); padding: 12px 0; }
article.judged header { color: var(--text-secondary); font-size: 13px; margin-bottom: 4px; }
.story p { margin: 0 0 8px; }
.pill { display: inline-block; background: var(--surface-2); border-radius: 999px; padding: 1px 10px; margin: 2px 4px 2px 0; font-size: 12px; }
.pill.topic { border: 1px solid var(--series-1); }
.judgment { margin-top: 6px; }
.rationale { color: var(--text-secondary); font-size: 13px; margin: 4px 0 0; }
ul.contexts { padding-left: 18px; }
</style>
</head>
<body>
<main>
<h1>Story Personalization Report</h1>
<p class="muted">Blinded AI judgment of stories generated under varied preference settings.</p>
<dl class="meta">
<dt>Location</dt><dd>${escapeHtml(location)}</dd>
<dt>Generation run</dt><dd>${escapeHtml(judgeMeta.run)} (started ${escapeHtml(runMeta.startedAt || '')}, commit ${escapeHtml(runMeta.gitCommit || '–')})</dd>
<dt>Varied factors</dt><dd>${escapeHtml(factors.join(', ') || 'none')}</dd>
<dt>Fixed preferences</dt><dd>${escapeHtml(
		Object.entries(runMeta.args?.base || {})
			.map(([key, value]) => `${key}=${value}`)
			.join(', ') || 'app defaults'
	)}</dd>
<dt>Story model</dt><dd>${escapeHtml(runMeta.configs?.[0]?.overrides?.aiModelAdvanced || units[0]?.preferences?.aiModelAdvanced || '–')}</dd>
<dt>Judge</dt><dd>${escapeHtml(judgeMeta.model)}, unit: ${escapeHtml(judgeMeta.unit)}, repeats: ${judgeMeta.repeats}, ${judgeMeta.withContext ? 'with' : 'without'} place context, judged ${escapeHtml(judgeMeta.judgedAt || '')}</dd>
</dl>
<div class="tiles">
<div class="tile"><div class="num">${runMeta.configs?.length ?? '–'}</div><div class="lbl">configurations</div></div>
<div class="tile"><div class="num">${units.length}</div><div class="lbl">judged ${escapeHtml(judgeMeta.unit)}s</div></div>
<div class="tile"><div class="num">${rows.length}</div><div class="lbl">judgments</div></div>
<div class="tile"><div class="num">${summary.overall.topicsPerText ?? '–'}</div><div class="lbl">topics per text</div></div>
</div>
<ul class="contexts">${contexts}</ul>
${factorSections}
<section>
<h2>All configurations</h2>
${renderGroupTable(summary.configs, 'Configuration')}
</section>
${consistency}
<section>
<h2>Judged texts</h2>
<p class="muted">Every generated text with its blind ratings and the judge's rationale.</p>
${renderJudgedTexts(runMeta, rows, units)}
</section>
</main>
</body>
</html>`;
}

// ---------------------------------------------------------------------------

async function main() {
	const args = parseArgs(process.argv.slice(2));
	const runMeta = JSON.parse(readFileSync(path.join(args.run, 'run.json'), 'utf8'));
	const records = readJsonl(path.join(args.run, 'results.jsonl'));
	const units = buildUnits(records, args.unit);
	const contexts = args.withContext ? loadContexts(args.run) : new Map();
	const judgmentsFile = path.join(args.run, 'judgments.jsonl');
	const judgeMetaFile = path.join(args.run, 'judgments-meta.json');

	let judgeMeta;
	if (args.reportOnly) {
		if (!existsSync(judgmentsFile)) {
			throw new Error(`No judgments.jsonl in ${args.run}; run without --report-only first`);
		}
		judgeMeta = existsSync(judgeMetaFile)
			? JSON.parse(readFileSync(judgeMetaFile, 'utf8'))
			: { run: displayPath(args.run), model: args.model, unit: args.unit, repeats: args.repeats };
		out(`Rebuilding report from ${displayPath(judgmentsFile)} ...`);
	} else {
		const total = units.length * args.repeats;
		out('Story personalization judgment');
		out(`  Run:            ${displayPath(args.run)}`);
		out(
			`  Texts:          ${units.length} ${args.unit}(s) from ${records.filter((record) => record.text).length} generated segments`
		);
		out(`  Repeats:        ${args.repeats} judgment(s) per text`);
		out(
			`  Judge requests: ${units.length} × ${args.repeats} = ${total} (${args.model}, reasoning effort "${AI_REASONING_EFFORT.JUDGE}")`
		);
		out(
			`  Context:        ${args.withContext ? 'place context shown' : 'text only'}; preferences are never shown`
		);
		out(`  Concurrency:    ${args.concurrency}`);
		out('');
		if (args.dryRun) {
			out('Dry run, nothing judged.');
			return;
		}
		if (!args.yes && !(await confirm('Proceed with judging? [y/N] '))) {
			out('Aborted.');
			return;
		}
		if (!existsSync(path.join(rootDir, 'src/.openai_api_key.js'))) {
			throw new Error('OpenAI key file missing: src/.openai_api_key.js (see README)');
		}
		const { openai } = await import(pathToFileURL(path.join(rootDir, 'src/util/ai-core.js')));

		judgeMeta = {
			run: displayPath(args.run),
			model: args.model,
			unit: args.unit,
			repeats: args.repeats,
			withContext: args.withContext,
			judgedAt: new Date().toISOString(),
			requests: total
		};
		writeFileSync(judgmentsFile, '');
		let completed = 0;
		let failed = 0;
		const usage = { inputTokens: 0, outputTokens: 0 };
		const tasks = units.flatMap((unit) =>
			Array.from({ length: args.repeats }, (_, repeatIndex) => async () => {
				const startedAt = Date.now();
				const row = {
					unitId: unit.id,
					configId: unit.configId,
					configLabel: unit.configLabel,
					contextId: unit.contextId,
					retry: unit.retry,
					segment: unit.segment,
					repeat: repeatIndex + 1,
					varied: unit.varied,
					preferences: unit.preferences,
					model: args.model
				};
				try {
					const contextDescription = args.withContext
						? describeContext(contexts.get(unit.contextId))
						: '';
					const result = await judgeText(openai, args.model, unit.text, contextDescription);
					row.judgment = result.judgment;
					row.responseId = result.responseId;
					row.usage = result.usage;
					usage.inputTokens += result.usage?.input_tokens || 0;
					usage.outputTokens += result.usage?.output_tokens || 0;
				} catch (error) {
					row.error = error?.message || String(error);
					failed++;
				}
				row.durationMs = Date.now() - startedAt;
				appendFileSync(judgmentsFile, `${JSON.stringify(row)}\n`);
				completed++;
				const status = row.error
					? `FAILED: ${row.error}`
					: DIMENSIONS.map(
							(dimension) => `${dimension.key[0]}=${row.judgment[dimension.key]}`
						).join(' ') + ` topics=${row.judgment.topics.join(',') || '-'}`;
				out(
					`  [${String(completed).padStart(String(total).length)}/${total}] ${unit.id} judgment ${row.repeat}: ${status}, ${(row.durationMs / 1000).toFixed(1)}s`
				);
			})
		);
		await runPool(tasks, args.concurrency);
		judgeMeta.completed = completed - failed;
		judgeMeta.failed = failed;
		judgeMeta.usage = usage;
		writeFileSync(judgeMetaFile, JSON.stringify(judgeMeta, null, 2));
		out('');
		out(
			`Judged ${completed - failed} text(s), failed: ${failed}; tokens: input ${usage.inputTokens}, output ${usage.outputTokens}`
		);
		if (failed) {
			process.exitCode = 1;
		}
	}

	const rows = readJsonl(judgmentsFile)
		.filter((row) => row.judgment)
		.map((row) => ({ ...row, match: topicMatch(row.judgment, row.preferences) }));
	if (!rows.length) {
		throw new Error('No successful judgments to summarize');
	}
	const summary = aggregate(runMeta, rows);
	writeFileSync(path.join(args.run, 'judgments-summary.json'), JSON.stringify(summary, null, 2));
	const reportFile = path.join(args.run, 'report.html');
	writeFileSync(reportFile, renderReport(runMeta, judgeMeta, summary, rows, units));
	out(`Report: ${displayPath(reportFile)}`);
}

main().catch((error) => {
	process.stderr.write(`${error.stack || error.message || error}\n`);
	process.exit(1);
});
